+import {addUsage, shouldContinueToolLoop} from './orchestratorHelpers.js';
 import type {ToolRegistry} from './tools/registry.js';
 import type {ToolCall} from '../types/ai.js';

@@ -24,3 +24,27 @@ describe('shouldContinueToolLoop', () => {
     expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
   });
 });
+
+describe('addUsage', () => {
+  const ROUND = {inputTokens: 5, outputTokens: 2, totalTokens: 7};
+
+  it('sums each token field of two reported rounds', () => {
+    expect(addUsage(ROUND, {inputTokens: 1, outputTokens: 3, totalTokens: 4})).toEqual({
+      inputTokens: 6,
+      outputTokens: 5,
+      totalTokens: 11,
+    });
+  });
+
+  it('adopts the round usage when no earlier round reported any', () => {
+    expect(addUsage(undefined, ROUND)).toEqual(ROUND);
+  });
+
